// Sidebar behavior: highlight the active nav link, collapsible nav sections,
// and nav label tooltips. The markup this script targets is generated by
// wiki-build-preamble in publish.el.
(function () {
  var path = window.location.pathname;
  document.querySelectorAll('nav a').forEach(function (a) {
    var dir = a.getAttribute('href').replace('index.html', '');
    var match = (dir === '/') ? (path === '/' || path === '/index.html')
                              : path.startsWith(dir);
    if (match) a.classList.add('active');
  });

  // ── Collapsible nav sections ──
  // Each section's open/closed state is keyed by the parent link's href and
  // persisted in localStorage so it survives navigation between pages.
  var COLLAPSE_KEY = 'navCollapsed';
  var collapsedState = {};
  try { collapsedState = JSON.parse(localStorage.getItem(COLLAPSE_KEY)) || {}; }
  catch (e) { collapsedState = {}; }

  function liKey(li) {
    var link = li.querySelector(':scope > .nav-row > a');
    return link ? link.getAttribute('href') : null;
  }
  function setCollapsed(li, isCollapsed) {
    li.classList.toggle('collapsed', isCollapsed);
    var toggle = li.querySelector(':scope > .nav-row > .nav-toggle');
    if (toggle) toggle.setAttribute('aria-expanded', String(!isCollapsed));
  }

  document.querySelectorAll('nav .nav-toggle').forEach(function (toggle) {
    var li = toggle.closest('li');
    var key = liKey(li);
    if (key && collapsedState[key]) setCollapsed(li, true);
    toggle.addEventListener('click', function (e) {
      e.preventDefault();
      var nowCollapsed = !li.classList.contains('collapsed');
      setCollapsed(li, nowCollapsed);
      if (key) {
        collapsedState[key] = nowCollapsed;
        try { localStorage.setItem(COLLAPSE_KEY, JSON.stringify(collapsedState)); }
        catch (e2) {}
      }
    });
  });

  // Always keep the current page reachable: expand every ancestor section.
  document.querySelectorAll('nav a.active').forEach(function (a) {
    var node = a.closest('li');
    while (node) {
      setCollapsed(node, false);
      var parent = node.parentElement;
      node = parent ? parent.closest('li') : null;
    }
  });

  // ── Light/dark theme toggle ──
  // The theme itself is applied before paint by an inline script in <head>
  // (see wiki-html-head in publish.el), which sets data-theme on <html> from
  // localStorage or the OS preference. Here we just wire up the button: label
  // it for the current theme and flip + persist the choice on click.
  var THEME_KEY = 'theme';
  var toggle = document.querySelector('.theme-toggle');
  if (toggle) {
    var iconEl = toggle.querySelector('.theme-toggle-icon');
    var labelEl = toggle.querySelector('.theme-toggle-label');
    var render = function () {
      var dark = document.documentElement.getAttribute('data-theme') === 'dark';
      // Icon shows what a click switches TO; label names the current theme.
      if (iconEl) iconEl.textContent = dark ? '☀' : '☽'; // ☀ / ☽
      if (labelEl) labelEl.textContent = dark ? 'Dark mode' : 'Light mode';
    };
    render();
    toggle.addEventListener('click', function () {
      var dark = document.documentElement.getAttribute('data-theme') === 'dark';
      var next = dark ? 'light' : 'dark';
      document.documentElement.setAttribute('data-theme', next);
      try { localStorage.setItem(THEME_KEY, next); } catch (e) {}
      render();
    });
  }

  // ── Nav label tooltips ──
  // Nav links are truncated with an ellipsis when a label is wider than the
  // sidebar. On hover, show the full label in a floating box, but only when
  // it's actually truncated (scrollWidth > clientWidth).
  var navTooltip = document.createElement('div');
  navTooltip.className = 'nav-tooltip';
  navTooltip.setAttribute('hidden', '');
  document.body.appendChild(navTooltip);

  document.querySelectorAll('nav .nav-tree a').forEach(function (a) {
    a.addEventListener('mouseenter', function () {
      if (a.scrollWidth <= a.clientWidth) return;
      var rect = a.getBoundingClientRect();
      navTooltip.textContent = a.textContent;
      navTooltip.removeAttribute('hidden');
      navTooltip.style.left = rect.right + 6 + 'px';
      navTooltip.style.top = rect.top + 'px';
    });
    a.addEventListener('mouseleave', function () {
      navTooltip.setAttribute('hidden', '');
    });
  });

  // ── Page table of contents ──
  // Org publishes the TOC as a bare nested list with a "Table of Contents"
  // heading. Here it becomes a card: a shorter label plus a section count, a
  // caret that folds the tree away (remembered across pages in localStorage),
  // and a data-cols hint so style.css splits a long TOC into two columns
  // instead of one very tall strip.
  var toc = document.getElementById('table-of-contents');
  if (toc) {
    var tocLinks = toc.querySelectorAll('#text-table-of-contents a');
    toc.classList.add('toc-enhanced');
    toc.setAttribute('data-cols', tocLinks.length > 8 ? '2' : '1');

    // A heading level skipped in the source leaves a link-less <li> wrapper;
    // flag it so CSS drops its empty indent step.
    toc.querySelectorAll('#text-table-of-contents li').forEach(function (li) {
      if (!li.querySelector(':scope > a')) li.classList.add('toc-anon');
    });

    var tocHead = toc.querySelector(':scope > h2');
    if (tocHead) {
      var TOC_KEY = 'tocCollapsed';
      tocHead.textContent = 'Contents';

      var tocCount = document.createElement('span');
      tocCount.className = 'toc-count';
      tocCount.textContent = tocLinks.length + (tocLinks.length === 1 ? ' section' : ' sections');
      tocHead.appendChild(tocCount);

      var tocBtn = document.createElement('button');
      tocBtn.type = 'button';
      tocBtn.className = 'toc-toggle';
      tocHead.appendChild(tocBtn);

      var setTocCollapsed = function (collapsed) {
        toc.classList.toggle('toc-collapsed', collapsed);
        tocBtn.setAttribute('aria-expanded', String(!collapsed));
        tocBtn.setAttribute('aria-label', collapsed ? 'Show contents' : 'Hide contents');
      };

      // Folded state is a deliberate choice once made; until then, a long TOC
      // starts folded on a phone, where one narrow column of 30-odd links
      // would otherwise push the page itself off the screen.
      var tocStored = null;
      try { tocStored = localStorage.getItem(TOC_KEY); } catch (e) {}
      setTocCollapsed(tocStored === null
        ? (window.innerWidth <= 768 && tocLinks.length > 12)
        : tocStored === '1');

      // The listener lives on the header, so a click anywhere along the bar —
      // label or caret — folds it; the button's click just bubbles up here.
      tocHead.addEventListener('click', function () {
        var collapsed = !toc.classList.contains('toc-collapsed');
        setTocCollapsed(collapsed);
        try { localStorage.setItem(TOC_KEY, collapsed ? '1' : '0'); } catch (e) {}
      });
    }
  }

  // ── Mobile off-canvas nav ──
  // On phones the sidebar is hidden off-screen (see the max-width:768px media
  // query in style.css) and opened via a hamburger button. The button and the
  // dimming backdrop are created here, and appended to <body> rather than into
  // #preamble on purpose: the drawer is moved with a CSS transform, and a
  // transformed element becomes the containing block for its position:fixed
  // descendants — so a button nested inside #preamble would slide away with it.
  var body = document.body;

  var navBtn = document.createElement('button');
  navBtn.type = 'button';
  navBtn.className = 'nav-open-btn';
  navBtn.setAttribute('aria-label', 'Open navigation');
  navBtn.setAttribute('aria-expanded', 'false');
  navBtn.innerHTML = '<span class="nav-open-btn-icon" aria-hidden="true">☰</span>';
  body.appendChild(navBtn);

  var navBackdrop = document.createElement('div');
  navBackdrop.className = 'nav-backdrop';
  body.appendChild(navBackdrop);

  var navIcon = navBtn.querySelector('.nav-open-btn-icon');
  function setNavOpen(open) {
    body.classList.toggle('nav-open', open);
    navBtn.setAttribute('aria-expanded', String(open));
    navBtn.setAttribute('aria-label', open ? 'Close navigation' : 'Open navigation');
    if (navIcon) navIcon.textContent = open ? '✕' : '☰'; // ✕ when open, ☰ when closed
  }

  navBtn.addEventListener('click', function () {
    setNavOpen(!body.classList.contains('nav-open'));
  });
  navBackdrop.addEventListener('click', function () { setNavOpen(false); });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') setNavOpen(false);
  });
  // Tapping a destination link closes the drawer so it isn't left open over an
  // in-page anchor jump. (Cross-page links reload anyway, resetting the state.)
  document.querySelectorAll('nav .nav-tree a').forEach(function (a) {
    a.addEventListener('click', function () { setNavOpen(false); });
  });
}());
